"""Embedded web-remote assets.

Generated from the top-level web/ directory so the phone remote remains available
even if a packaging tool relocates or omits external static files.
"""
from __future__ import annotations

EMBEDDED_WEB: dict[str, tuple[str, bytes]] = {
    'app.js': ('text/javascript', b'(() => {\n  const $ = (id) => document.getElementById(id);\n  const overlay = $(\'pairOverlay\');\n  const toast = $(\'toast\');\n  let paired = false;\n  let busy = false;\n  let lastState = null;\n  let toastTimer = null;\n\n  function showToast(message) {\n    toast.textContent = message;\n    toast.classList.add(\'show\');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(() => toast.classList.remove(\'show\'), 1700);\n  }\n\n  function formatClock(seconds) {\n    const ms = Math.max(0, Math.floor((Number(seconds) || 0) * 1000));\n    const h = Math.floor(ms / 3600000);\n    const m = Math.floor((ms % 3600000) / 60000);\n    const s = Math.floor((ms % 60000) / 1000);\n    const rem = ms % 1000;\n    return `${String(h).padStart(2,\'0\')}:${String(m).padStart(2,\'0\')}:${String(s).padStart(2,\'0\')}.${String(rem).padStart(3,\'0\')}`;\n  }\n\n  function dbPercent(db) {\n    const value = Math.max(-60, Math.min(0, Number(db) || -80));\n    return ((value + 60) / 60) * 100;\n  }\n\n  function setConnection(mode, text) {\n    const pill = $(\'connectionPill\');\n    pill.classList.remove(\'ready\', \'offline\');\n    if (mode) pill.classList.add(mode);\n    $(\'connectionText\').textContent = text;\n  }\n\n  function buildMeters(state) {\n    const wrap = $(\'meters\');\n    const names = state.tracks || [];\n    const meters = state.meters || [];\n    const armed = state.armed || [];\n    const count = Math.max(names.length, meters.length, 4);\n    if (wrap.children.length !== count) {\n      wrap.innerHTML = \'\';\n      for (let i = 0; i < count; i++) {\n        const row = document.createElement(\'div\');\n        row.className = \'meter-row\';\n        row.innerHTML = `\n          <div class="meter-name"><small>CH ${String(i+1).padStart(2,\'0\')}</small><b data-name></b></div>\n          <div class="meter-track"><div class="meter-fill" data-fill></div></div>\n          <div class="meter-db" data-db>\xe2\x88\x92\xe2\x88\x9e</div>`;\n        wrap.appendChild(row);\n      }\n    }\n    [...wrap.children].forEach((row, i) => {\n      const db = Number(meters[i] ?? -80);\n      row.querySelector(\'[data-name]\').textContent = names[i] || `Track ${i+1}`;\n      row.querySelector(\'[data-fill]\').style.width = `${dbPercent(db)}%`;\n      row.querySelector(\'[data-fill]\').style.opacity = armed[i] === false ? \'.25\' : \'1\';\n      row.querySelector(\'[data-db]\').textContent = db <= -79 ? \'\xe2\x88\x92\xe2\x88\x9e\' : `${db.toFixed(1)}`;\n    });\n  }\n\n  function render(state) {\n    lastState = state;\n    $(\'projectName\').textContent = state.project || \'FilmSet Recorder\';\n    $(\'roll\').textContent = state.roll || \'\xe2\x80\x94\';\n    $(\'scene\').textContent = state.scene || \'\xe2\x80\x94\';\n    $(\'take\').textContent = String(state.take ?? \'\xe2\x80\x94\').padStart(3, \'0\');\n    $(\'clock\').textContent = formatClock(state.elapsed);\n    $(\'xruns\').textContent = state.xruns ?? 0;\n    $(\'drops\').textContent = state.dropped_blocks ?? 0;\n    $(\'audioState\').textContent = state.audio_ready ? \'READY\' : \'OFFLINE\';\n    $(\'diskState\').textContent = state.disk_display || \'\xe2\x80\x94\';\n\n    const circle = !!state.circle;\n    $(\'circleButton\').classList.toggle(\'active\', circle);\n    $(\'circleTop\').classList.toggle(\'active\', circle);\n\n    const label = $(\'stateLabel\');\n    label.classList.remove(\'recording\', \'playing\');\n    $(\'recordButton\').classList.toggle(\'recording\', !!state.recording);\n    if (state.recording) {\n      label.textContent = \'\xe2\x97\x8f RECORDING\';\n      label.classList.add(\'recording\');\n    } else if (state.playing) {\n      label.textContent = \'\xe2\x96\xb6 PLAYING\';\n      label.classList.add(\'playing\');\n    } else {\n      label.textContent = state.audio_ready ? \'READY\' : \'AUDIO OFFLINE\';\n    }\n    buildMeters(state);\n  }\n\n  async function jsonFetch(url, options = {}) {\n    const response = await fetch(url, {\n      ...options,\n      cache: \'no-store\',\n      credentials: \'same-origin\',\n      headers: {\'Content-Type\':\'application/json\', ...(options.headers || {})}\n    });\n    let body = {};\n    try { body = await response.json(); } catch (_) {}\n    if (!response.ok) {\n      const error = new Error(body.error || `HTTP ${response.status}`);\n      error.status = response.status;\n      throw error;\n    }\n    return body;\n  }\n\n  async function pair() {\n    const pin = $(\'pinInput\').value.replace(/\\D/g, \'\').slice(0, 6);\n    $(\'pinInput\').value = pin;\n    if (pin.length !== 6) {\n      $(\'pairError\').textContent = \'Enter all six digits.\';\n      return;\n    }\n    $(\'pairError\').textContent = \'\';\n    try {\n      await jsonFetch(\'/api/pair\', {method:\'POST\', body:JSON.stringify({pin})});\n      paired = true;\n      overlay.classList.add(\'hidden\');\n      showToast(\'Remote paired\');\n      await poll();\n    } catch (err) {\n      $(\'pairError\').textContent = err.message || \'Pairing failed.\';\n    }\n  }\n\n  async function command(command, extra = {}) {\n    if (!paired) return;\n    try {\n      await jsonFetch(\'/api/command\', {\n        method:\'POST\',\n        body:JSON.stringify({command, request_id: `${Date.now()}-${Math.random()}`, ...extra})\n      });\n    } catch (err) {\n      if (err.status === 401) requirePairing();\n      else showToast(err.message || \'Command failed\');\n    }\n  }\n\n  function requirePairing() {\n    paired = false;\n    overlay.classList.remove(\'hidden\');\n    setConnection(\'offline\', \'PAIRING\');\n  }\n\n  async function poll() {\n    if (busy) return;\n    busy = true;\n    try {\n      const state = await jsonFetch(\'/api/status\');\n      paired = true;\n      overlay.classList.add(\'hidden\');\n      setConnection(\'ready\', \'CONNECTED\');\n      render(state);\n    } catch (err) {\n      if (err.status === 401) requirePairing();\n      else setConnection(\'offline\', \'OFFLINE\');\n    } finally {\n      busy = false;\n    }\n  }\n\n  $(\'pairButton\').addEventListener(\'click\', pair);\n  $(\'pinInput\').addEventListener(\'keydown\', e => { if (e.key === \'Enter\') pair(); });\n  $(\'pinInput\').addEventListener(\'input\', e => { e.target.value = e.target.value.replace(/\\D/g,\'\').slice(0,6); });\n  $(\'recordButton\').addEventListener(\'click\', () => command(\'record\'));\n  $(\'stopButton\').addEventListener(\'click\', () => command(\'stop\'));\n  $(\'playButton\').addEventListener(\'click\', () => command(\'play\'));\n  $(\'nextButton\').addEventListener(\'click\', () => command(\'next_take\'));\n  $(\'circleButton\').addEventListener(\'click\', () => command(\'toggle_circle\'));\n  $(\'circleTop\').addEventListener(\'click\', () => command(\'toggle_circle\'));\n  $(\'sceneBox\').addEventListener(\'click\', () => {\n    if (!lastState || lastState.recording) return;\n    const value = prompt(\'Scene\', lastState.scene || \'\');\n    if (value !== null && value.trim()) command(\'set_scene\', {scene:value.trim()});\n  });\n  $(\'takeBox\').addEventListener(\'click\', () => {\n    if (!lastState || lastState.recording) return;\n    const value = prompt(\'Take number\', lastState.take || 1);\n    const n = Number.parseInt(value, 10);\n    if (Number.isFinite(n) && n > 0) command(\'set_take\', {take:n});\n  });\n  $(\'unpairButton\').addEventListener(\'click\', async () => {\n    try { await jsonFetch(\'/api/unpair\', {method:\'POST\', body:\'{}\'}); } catch (_) {}\n    requirePairing();\n  });\n\n  // Initial probe. A QR code can provide the PIN in the URL fragment; fragments are\n  // never sent to the server, and we remove it from browser history immediately.\n  (async () => {\n    const match = window.location.hash.match(/(?:^#|&)pin=(\\d{6})(?:&|$)/);\n    if (match) {\n      $(\'pinInput\').value = match[1];\n      history.replaceState(null, \'\', window.location.pathname + window.location.search);\n      await pair();\n    }\n    try {\n      const info = await jsonFetch(\'/api/info\');\n      $(\'projectName\').textContent = info.project || \'Remote Control\';\n    } catch (_) {}\n    await poll();\n  })();\n  setInterval(poll, 150);\n})();\n'),
    'index.html': ('text/html', b'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />\n  <meta name="theme-color" content="#090c10" />\n  <meta name="apple-mobile-web-app-capable" content="yes" />\n  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />\n  <meta name="apple-mobile-web-app-title" content="FilmSet Remote" />\n  <title>FilmSet Remote</title>\n  <link rel="manifest" href="/manifest.webmanifest" />\n  <link rel="icon" href="/remote-icon.svg" type="image/svg+xml" />\n  <link rel="stylesheet" href="/styles.css" />\n</head>\n<body>\n  <div id="app" class="shell">\n    <header class="topbar">\n      <div>\n        <div class="eyebrow">FILMSET RECORDER</div>\n        <div class="project" id="projectName">Remote Control</div>\n      </div>\n      <div class="connection" id="connectionPill"><span class="dot"></span><span id="connectionText">CONNECTING</span></div>\n    </header>\n\n    <main>\n      <section class="slate-card">\n        <div class="slate-grid">\n          <div class="slate-item"><span>ROLL</span><strong id="roll">\xe2\x80\x94</strong></div>\n          <div class="slate-item editable" id="sceneBox"><span>SCENE</span><strong id="scene">\xe2\x80\x94</strong></div>\n          <div class="slate-item editable" id="takeBox"><span>TAKE</span><strong id="take">\xe2\x80\x94</strong></div>\n          <button class="circle-chip" id="circleTop" aria-label="Circle take">\xe2\x98\x85</button>\n        </div>\n        <div class="clock" id="clock">00:00:00.000</div>\n        <div class="state" id="stateLabel">READY</div>\n      </section>\n\n      <section class="meters-card" id="meters"></section>\n\n      <section class="transport-card">\n        <button class="record-button" id="recordButton"><span class="record-dot"></span>RECORD</button>\n        <div class="transport-row">\n          <button class="transport-button stop" id="stopButton">\xe2\x96\xa0 STOP</button>\n          <button class="transport-button" id="playButton">\xe2\x96\xb6 PLAY LAST</button>\n        </div>\n        <div class="transport-row">\n          <button class="transport-button" id="nextButton">NEXT TAKE</button>\n          <button class="transport-button circle" id="circleButton">\xe2\x98\x85 CIRCLE</button>\n        </div>\n      </section>\n\n      <section class="health-card">\n        <div><span>INTERFACE</span><strong id="audioState">\xe2\x80\x94</strong></div>\n        <div><span>DISK</span><strong id="diskState">\xe2\x80\x94</strong></div>\n        <div><span>XRUN</span><strong id="xruns">0</strong></div>\n        <div><span>DROPS</span><strong id="drops">0</strong></div>\n      </section>\n\n      <button class="settings-button" id="unpairButton">Disconnect this phone</button>\n    </main>\n  </div>\n\n  <div class="overlay" id="pairOverlay">\n    <div class="pair-card">\n      <div class="pair-logo"><span></span></div>\n      <div class="eyebrow">FILMSET RECORDER</div>\n      <h1>Pair this device</h1>\n      <p>Enter the six-digit code shown in FilmSet Recorder on the recording computer.</p>\n      <input id="pinInput" inputmode="numeric" pattern="[0-9]*" maxlength="6" autocomplete="one-time-code" placeholder="000000" aria-label="Pairing code" />\n      <button id="pairButton">PAIR REMOTE</button>\n      <div class="pair-error" id="pairError"></div>\n      <div class="pair-hint" id="pairHint">The phone and recorder must be on the same Wi-Fi network.</div>\n    </div>\n  </div>\n\n  <div class="toast" id="toast"></div>\n  <script src="/app.js"></script>\n</body>\n</html>\n'),
    'manifest.webmanifest': ('application/manifest+json', b'{\n  "name": "FilmSet Recorder Remote",\n  "short_name": "FilmSet Remote",\n  "start_url": "/",\n  "display": "standalone",\n  "background_color": "#090c10",\n  "theme_color": "#090c10",\n  "icons": [\n    {"src":"/remote-icon.svg","sizes":"any","type":"image/svg+xml","purpose":"any maskable"}\n  ]\n}\n'),
    'remote-icon.svg': ('image/svg+xml', b'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">\n  <rect width="512" height="512" rx="110" fill="#0b0f14"/>\n  <circle cx="256" cy="256" r="116" fill="#ff3b30" opacity=".13"/>\n  <circle cx="256" cy="256" r="66" fill="#ff3b30"/>\n</svg>\n'),
    'styles.css': ('text/css', b':root {\n  color-scheme: dark;\n  --bg: #090c10;\n  --panel: rgba(20, 25, 31, .92);\n  --panel-2: #11161c;\n  --line: #252d36;\n  --text: #f5f7fa;\n  --muted: #8994a1;\n  --accent: #ff3b30;\n  --accent-soft: rgba(255, 59, 48, .16);\n  --green: #32d583;\n  --amber: #fdb022;\n  --shadow: 0 22px 70px rgba(0,0,0,.36);\n}\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\nhtml, body { margin:0; min-height:100%; background:var(--bg); color:var(--text); font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }\nbody { background: radial-gradient(circle at 50% -20%, #1b2530 0%, var(--bg) 38%); }\nbutton, input { font: inherit; }\nbutton { touch-action: manipulation; }\n.shell { width:min(680px, 100%); margin:0 auto; min-height:100vh; padding: max(18px, env(safe-area-inset-top)) 16px max(26px, env(safe-area-inset-bottom)); }\n.topbar { display:flex; align-items:center; justify-content:space-between; gap:14px; padding: 4px 2px 15px; }\n.eyebrow { font-size:11px; font-weight:800; letter-spacing:.16em; color:#a9b3bf; }\n.project { margin-top:4px; font-size:18px; font-weight:720; letter-spacing:-.02em; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:260px; }\n.connection { border:1px solid var(--line); background:rgba(255,255,255,.035); border-radius:999px; padding:8px 11px; font-size:10px; font-weight:800; letter-spacing:.08em; display:flex; align-items:center; gap:7px; white-space:nowrap; }\n.connection .dot { width:7px; height:7px; border-radius:50%; background:var(--amber); box-shadow:0 0 14px currentColor; }\n.connection.ready .dot { background:var(--green); }\n.connection.offline .dot { background:var(--accent); }\nmain { display:grid; gap:12px; }\n.slate-card, .meters-card, .transport-card, .health-card { border:1px solid var(--line); background:linear-gradient(160deg, rgba(24,29,36,.96), rgba(14,18,23,.96)); border-radius:20px; box-shadow:var(--shadow); }\n.slate-card { padding:16px; }\n.slate-grid { display:grid; grid-template-columns: 1fr 1.3fr 1fr 44px; gap:8px; }\n.slate-item { background:#0b0f14; border:1px solid #212933; border-radius:12px; padding:9px 11px; min-width:0; }\n.slate-item span { display:block; color:var(--muted); font-size:9px; font-weight:800; letter-spacing:.13em; }\n.slate-item strong { display:block; margin-top:3px; font-size:17px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n.slate-item.editable { cursor:pointer; }\n.circle-chip { border:1px solid #303844; border-radius:12px; background:#0b0f14; color:#697481; font-size:22px; }\n.circle-chip.active { color:#ffd166; border-color:rgba(255,209,102,.6); background:rgba(255,209,102,.08); }\n.clock { text-align:center; font-variant-numeric:tabular-nums; letter-spacing:-.045em; font-weight:760; font-size:clamp(40px, 12vw, 70px); margin-top:19px; line-height:1; }\n.state { text-align:center; margin-top:9px; color:var(--green); font-size:12px; font-weight:900; letter-spacing:.18em; }\n.state.recording { color:#ff655c; }\n.state.playing { color:#74a7ff; }\n.meters-card { padding:8px 12px; }\n.meter-row { display:grid; grid-template-columns: minmax(76px, 1fr) 3.2fr 48px; gap:10px; align-items:center; min-height:49px; border-bottom:1px solid rgba(255,255,255,.055); }\n.meter-row:last-child { border-bottom:0; }\n.meter-name { min-width:0; }\n.meter-name b { display:block; font-size:13px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n.meter-name small { color:var(--muted); font-size:9px; font-weight:800; letter-spacing:.11em; }\n.meter-track { height:12px; background:#090d11; border:1px solid #252d36; border-radius:999px; overflow:hidden; position:relative; }\n.meter-fill { height:100%; width:0%; border-radius:999px; background:linear-gradient(90deg, #2fca79 0 68%, #f6c445 82%, #ff5a52 100%); transition:width .08s linear; }\n.meter-db { text-align:right; font-variant-numeric:tabular-nums; font-size:11px; color:#b8c1cb; }\n.transport-card { padding:12px; display:grid; gap:10px; }\n.record-button { min-height:78px; border:1px solid rgba(255,83,73,.7); border-radius:17px; background:linear-gradient(180deg, #ff4b41, #da241d); color:white; font-size:22px; font-weight:900; letter-spacing:.04em; box-shadow:0 12px 34px rgba(255,59,48,.18); }\n.record-button:active { transform:scale(.992); }\n.record-button.recording { animation: pulse 1.35s infinite; }\n.record-dot { display:inline-block; width:14px; height:14px; border-radius:50%; background:white; margin-right:10px; vertical-align:-1px; }\n.transport-row { display:grid; grid-template-columns:1fr 1fr; gap:10px; }\n.transport-button { min-height:58px; border:1px solid #313a45; border-radius:14px; background:#151b22; color:var(--text); font-size:13px; font-weight:850; letter-spacing:.04em; }\n.transport-button:active { background:#1d2630; transform:scale(.99); }\n.transport-button.stop { border-color:#4c3433; }\n.transport-button.circle.active { color:#ffd166; border-color:#7f6d3d; background:#242015; }\n.health-card { padding:12px; display:grid; grid-template-columns:1fr 1fr; gap:8px; }\n.health-card div { background:#0c1015; border:1px solid #212933; border-radius:12px; padding:10px; }\n.health-card span { display:block; font-size:8px; color:var(--muted); font-weight:850; letter-spacing:.13em; }\n.health-card strong { display:block; margin-top:4px; font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n.settings-button { border:0; color:#7f8995; background:transparent; padding:10px; font-size:11px; }\n.overlay { position:fixed; inset:0; background:rgba(3,5,7,.86); backdrop-filter:blur(18px); display:flex; align-items:center; justify-content:center; padding:22px; z-index:10; }\n.overlay.hidden { display:none; }\n.pair-card { width:min(420px, 100%); border:1px solid #29323c; background:#11161c; border-radius:24px; padding:28px 22px 22px; box-shadow:0 30px 90px rgba(0,0,0,.55); text-align:center; }\n.pair-logo { margin:0 auto 17px; width:54px; height:54px; border:1px solid #383f49; border-radius:17px; display:grid; place-items:center; background:#0b0f13; }\n.pair-logo span { width:18px; height:18px; border-radius:50%; background:var(--accent); box-shadow:0 0 0 7px rgba(255,59,48,.12); }\n.pair-card h1 { margin:8px 0 8px; font-size:28px; letter-spacing:-.04em; }\n.pair-card p { margin:0 auto 20px; max-width:330px; color:#9ba6b2; line-height:1.5; font-size:14px; }\n#pinInput { width:100%; background:#090d11; border:1px solid #303944; color:white; border-radius:14px; padding:15px; text-align:center; font-size:28px; font-weight:750; letter-spacing:.3em; outline:none; }\n#pinInput:focus { border-color:#647180; }\n#pairButton { width:100%; margin-top:12px; border:0; border-radius:14px; background:#f2f4f7; color:#0b0e12; padding:15px; font-weight:900; letter-spacing:.04em; }\n.pair-error { min-height:20px; margin-top:10px; color:#ff7168; font-size:12px; }\n.pair-hint { color:#68737f; font-size:10px; line-height:1.4; margin-top:5px; }\n.toast { position:fixed; left:50%; bottom:max(20px, env(safe-area-inset-bottom)); transform:translate(-50%, 30px); background:#eef1f4; color:#12161a; border-radius:999px; padding:10px 15px; font-size:12px; font-weight:800; opacity:0; pointer-events:none; transition:.18s ease; z-index:20; white-space:nowrap; max-width:90vw; overflow:hidden; text-overflow:ellipsis; }\n.toast.show { opacity:1; transform:translate(-50%, 0); }\n@keyframes pulse { 0%,100% { box-shadow:0 12px 34px rgba(255,59,48,.16); } 50% { box-shadow:0 12px 46px rgba(255,59,48,.42); } }\n@media (min-width:600px) {\n  .shell { padding-left:24px; padding-right:24px; }\n  main { grid-template-columns: 1fr 1fr; }\n  .slate-card, .meters-card, .transport-card { grid-column:1 / -1; }\n  .health-card { grid-column:1 / -1; grid-template-columns:repeat(4, 1fr); }\n  .settings-button { grid-column:1 / -1; }\n}\n'),
}
